mapper.select:
SELECT game_id, skill_key, process_key, name, activation_type, description, sort_order, created_at, updated_at
FROM public.skill_processes
WHERE game_id = #{gameId} AND skill_key = #{skillKey} AND process_key = #{processKey}

SELECT COUNT(1)
FROM public.skill_processes
WHERE game_id = #{gameId} AND skill_key = #{skillKey} AND process_key = #{processKey}

mapper.insert:
INSERT INTO public.skill_processes (
    game_id, skill_key, process_key, name, activation_type, description, sort_order
) VALUES (
    #{gameId}, #{skillKey}, #{processKey}, #{name}, #{activationType}, #{description}, #{sortOrder}
)

INSERT INTO public.skill_process_steps (
    game_id, skill_key, process_key, step_key, name, step_type, description, sort_order
) VALUES (
    #{gameId}, #{skillKey}, #{processKey}, #{stepKey}, #{name}, #{stepType}, #{description}, #{sortOrder}
)

mapper.update:
UPDATE public.skill_process_steps
SET name = #{name}, description = #{description}, sort_order = #{sortOrder}
WHERE game_id = #{gameId} AND skill_key = #{skillKey}
  AND process_key = #{processKey} AND step_key = #{stepKey}

mapper.delete:
DELETE FROM public.skill_process_steps
WHERE game_id = #{gameId} AND skill_key = #{skillKey} AND process_key = #{processKey}
  AND step_key IN
#{stepKey}

